// Repositorio en memoria para probar la app sin depender de PostgreSQL.
function iniciarServerDeTest(linksIniciales) {
  const links = structuredClone(linksIniciales || []);
  const repositorio = {
    async crear(link) {
      if (links.some(function (l) { return l.codigo === link.codigo; })) {
        return false;
      }
      links.push(structuredClone(link));
      return true;
    },
    async buscar(codigo) {
      const link = links.find(function (l) { return l.codigo === codigo; });
      return link ? structuredClone(link) : null;
    },
    async incrementarClicks(codigo) {
      const link = links.find(function (l) { return l.codigo === codigo; });
      if (!link) return null;
      link.clicks += 1;
      return structuredClone(link);
    },
    async verificarConexion() {
      return true;
    }
  };
  const { crearApp } = require('../src/server');
  const app = crearApp(repositorio);

