async function iniciar() {
  if (!process.env.DATABASE_URL) {
    throw new Error('Falta la variable de entorno DATABASE_URL');
  }

  const repositorio = conectarPostgres(process.env.DATABASE_URL);
  await repositorio.inicializar();

  // Migra una sola vez los links heredados; los codigos ya presentes nunca se pisan.
  for (const link of linksIniciales) {
    await repositorio.crear(link);
  }

  const app = crearApp(repositorio);
  const puerto = Number(process.env.PORT) || 3000;
  const server = app.listen(puerto, '0.0.0.0', function () {
    console.log(`Corta escuchando en el puerto ${puerto}`);
  });

  async function cerrar() {
    server.close(async function () {
      await repositorio.cerrar();
      process.exit(0);
    });
  }

  process.once('SIGTERM', cerrar);
  process.once('SIGINT', cerrar);

  return { app, server, repositorio };
}

"""Puntos de entrada de la entrega."""

from pathlib import Path
import os

from admision_tp.buscador import BuscadorBM25
from admision_tp.prompts import RAIZ, RUTA_ENTREGA, PromptSpec


def construir_buscador(ruta_normas: Path) -> BuscadorBM25:
    return BuscadorBM25(ruta_normas, variante=os.getenv("BUSCADOR_VARIANTE", "baseline"))


def cargar_prompt() -> PromptSpec:
    """PromptSpec de `PROMPT_SPEC` (relativa a la raíz del repo) o el de la entrega; valida su sha256."""
    ruta = Path(os.getenv("PROMPT_SPEC") or RUTA_ENTREGA)
    return PromptSpec.cargar(ruta if ruta.is_absolute() else RAIZ / ruta)


def construir_agente():
    from admision_tp.agente_prompt import AgentePrompt
    from admision_tp.configuracion import Configuracion
    from admision_tp.modelo import ModeloLocal

    prompt = cargar_prompt()  # antes de cargar el modelo: un prompt inválido falla sin usar la GPU
    return AgentePrompt(ModeloLocal.cargar(Configuracion.desde_entorno()), prompt)

def _normalizar(m):
    return m / np.linalg.norm(m, axis=1, keepdims=True).clip(min=1e-12)


class BertPromedio:
    """Linea de base obligatoria: BERT sin ajustar para similitud, embedding = promedio de los
    vectores de la ultima capa sobre los tokens reales (se ignora el padding)."""

    def __init__(self, modelo="google-bert/bert-base-multilingual-cased", lote=16):
        from transformers import AutoModel, AutoTokenizer

        self.nombre, self.lote = modelo, lote
        self.tokenizer = AutoTokenizer.from_pretrained(modelo)
        self.modelo = AutoModel.from_pretrained(modelo).eval()

    def _codificar(self, textos):
        import torch

        salidas = []
        with torch.no_grad():
            for i in range(0, len(textos), self.lote):
                enc = self.tokenizer(textos[i:i + self.lote], padding=True, truncation=True,
                                     max_length=512, return_tensors="pt")
                h = self.modelo(**enc).last_hidden_state
                m = enc["attention_mask"].unsqueeze(-1).float()
                salidas.append(((h * m).sum(1) / m.sum(1)).numpy())
        return _normalizar(np.concatenate(salidas))

    codificar_consultas = codificar_pasajes = _codificar

class SentenceTransformerEncoder:
    """Modelos entrenados para embeddings de oraciones (MiniLM, e5, bge-m3). Los e5 piden prefijos."""

    def __init__(self, modelo, prefijo_consulta="", prefijo_pasaje="", lote=16):
        from sentence_transformers import SentenceTransformer

        self.nombre, self.lote = modelo, lote
        self.prefijo_consulta, self.prefijo_pasaje = prefijo_consulta, prefijo_pasaje
        self.modelo = SentenceTransformer(modelo, device="cpu")

    def _codificar(self, textos, prefijo):
        m = self.modelo.encode([prefijo + t for t in textos], batch_size=self.lote,
                               normalize_embeddings=True, show_progress_bar=False)
        return np.asarray(m, dtype=np.float32)

    def codificar_consultas(self, textos):
        return self._codificar(textos, self.prefijo_consulta)

    def codificar_pasajes(self, textos):
        return self._codificar(textos, self.prefijo_pasaje)


def crear_encoder(cfg):
    """cfg: {"tipo": "bert_promedio" | "sentence_transformer", "modelo": ..., "prefijo_consulta": ..., "prefijo_pasaje": ...}"""
    if cfg["tipo"] == "bert_promedio":
        return BertPromedio(cfg["modelo"])
    if cfg["tipo"] == "sentence_transformer":
        return SentenceTransformerEncoder(cfg["modelo"], cfg.get("prefijo_consulta", ""), cfg.get("prefijo_pasaje", ""))
    raise ValueError(f"tipo de encoder desconocido: {cfg['tipo']}")

def circuito_esperado(row: dict[str, str]) -> str:
    if row["sospecha_sepsis"] != "no":
        return "codigo_sepsis"
    if row["motivo"] == "dolor tor\u00e1cico":
        return "ecg"
    if row["motivo"] == "signos neurol\u00f3gicos focales de inicio s\u00fabito":
        return "codigo_acv"
    return "ninguno"


def plazo_esperado(row: dict[str, str], parametros: dict[str, int]) -> str:
    circuito = circuito_esperado(row)
    bases = {
        "ecg": parametros["P-TDE-1"],
        "codigo_acv": parametros["P-TDE-2"],
        "codigo_sepsis": (
            parametros["P-TDE-3"]
            if row["sospecha_sepsis"] in {"probable", "con signos de shock"}
            else parametros["P-TDE-4"]
        ),
    }
    if circuito == "ninguno":
        return ""
    descuento = parametros["P-TDE-5"] if row["llegada"] == "en ambulancia" else 0
    return str(bases[circuito] - descuento)


def registro_esperado(row: dict[str, str], parametros: dict[str, int]) -> str:
    if not row["documento_tipo"]:
        return "provisorio"
    if row["documento_tipo"] == "DNI":
        return "definitivo"
    return "provisorio" if int(row["nivel"]) <= parametros["P-ADM-3"] else "definitivo"

def clasificar(
    rows: list[dict[str, str]],
    parametros: dict[str, int],
    trazas: dict | None = None,
) -> tuple[list[dict[str, str]], dict]:
    costumbres = inferir_costumbres(rows, parametros, trazas)
    razones = {row["id"]: razones_normativas(row, parametros) for row in rows}
    ids_ruido = {i for costumbre in costumbres for i in costumbre.get("ids_ruido", [])}
    salida = []
    for row in rows:
        tipo = "error" if razones[row["id"]] else "ruido" if row["id"] in ids_ruido else "correcta"
        salida.append({"id": row["id"], "tipo": tipo})
    return salida, {
        "costumbres": costumbres,
        "desvios_por_operador": desvios_por_operador(costumbres, rows),
    }

async def _ejecutar(por_nombre, llamada):
    tool = por_nombre.get(llamada["name"])
    if tool is None:
        return ToolMessage(f"Error: la herramienta '{llamada['name']}' no existe. Herramientas disponibles: "
                           f"{', '.join(sorted(por_nombre))}.", tool_call_id=llamada["id"], name=llamada["name"])
    try:
        return await tool.ainvoke({**llamada, "type": "tool_call"})
    except Exception as e:  # el error vuelve al modelo como texto para que pueda corregirse
        return ToolMessage(f"Error al ejecutar {llamada['name']}: {e}", tool_call_id=llamada["id"], name=llamada["name"])


async def responder(llm, tools, pregunta):
    """Devuelve todos los mensajes de la conversación: sistema, pregunta, AIMessage y ToolMessage."""
    llm_con_tools = llm.bind_tools(tools)
    por_nombre = {t.name: t for t in tools}
    mensajes = [SystemMessage(PROMPT), HumanMessage(pregunta)]
    for _ in range(MAX_PASOS):
        ai = await llm_con_tools.ainvoke(mensajes)
        mensajes.append(ai)
        if not ai.tool_calls:
            break
        for llamada in ai.tool_calls:
            mensajes.append(await _ejecutar(por_nombre, llamada))
    return mensajes
